import six
import yaml
import logging
from .entrypoint import EntryPoint
from abc import ABCMeta, abstractmethod
from .base_config import BaseConfig


@six.add_metaclass(ABCMeta)
class BaseProvider:

    def __init__(self):
        self._config = None
        self._entry_point = EntryPoint()

    @abstractmethod
    def load(self, **kwargs):
        pass

    @property
    def config(self):
        return self._config


class PrismaProvider(BaseProvider):

    def __init__(self):
        BaseProvider.__init__(self)

    def load(self, yaml_file, testline_configuration):
        with open(yaml_file) as fh:
            yaml_dict = yaml.load(fh.read(), Loader=yaml.FullLoader)
            yaml_dict = self._add_testline_config_in_yaml_dict(testline_configuration, yaml_dict)
            self._config = BaseConfig(yaml_dict)
        self._extend_components()
        return self._config

    def _extend_components(self):
        component_path_list = self._config.get_entity_path_list('components')
        for component_path in component_path_list:
            component_names = self._config[component_path]
            components_dict = {}
            for node_name in component_names:
                provider = self._entry_point.get_provider_instance(self._config[node_name].type)
                provider.load(self._config, node_name)
                components_dict[node_name] = provider.config
            self._config[component_path] = BaseConfig(components_dict)

    def _add_testline_config_in_yaml_dict(self, testline_configuration, yaml_dict):
        add_tl_config = {}
        for node_name in yaml_dict:
            for tl_config_name in ['executor', 'harness']:
                if tl_config_name in yaml_dict[node_name]:
                    config_keys = yaml_dict[node_name][tl_config_name]
                    if config_keys not in add_tl_config:
                        add_tl_config[config_keys] = self._parse_configuration(config_keys, testline_configuration)
                        if tl_config_name == 'executor':
                            add_tl_config[config_keys]['type'] = 'executor.ssh'
        return dict(list(yaml_dict.items()) + list(add_tl_config.items()))

    def _parse_configuration(self, conf_keys, configuration):
        """
        parse  configuration for given  key for section of configuration

        :param conf_keys: Key to access remote host/ Testline information
        :param configuration: remote host/ Testline information
        :return:
        """

        if conf_keys is None:
            return dict(configuration)
        elif conf_keys.startswith('tl'):
            try:
                from robot.libraries.BuiltIn import BuiltIn
                testline = conf_keys.split('.')
                configuration = BuiltIn().get_variable_value('${' + testline[0] + '}')
                del testline[0]
                testline.insert(0, "configuration")
                conf_keys = ".".join(testline)
                logging.debug(conf_keys)
                # remove
                return eval(conf_keys).__dict__
            except KeyError:
                logging.error(conf_keys + " is  missing")
            except ImportError:
                logging.error("Robot Framework is not available")
        else:
            return eval('configuration.' + conf_keys).__dict__


class NodeProvider(BaseProvider):

    def __init__(self):
        BaseProvider.__init__(self)

    def load(self, configuration, node_name):
        self._config = configuration
        if "executor" in self._config[node_name].keys():
            executor_name = self._config[node_name]["executor"]
            executor_provider = self._entry_point.get_provider_instance("ue.prisma.executor")
            executor_provider.load(self._config, executor_name)
            self._config[node_name]["executor"] = executor_provider.config
        if 'harness' in self._config[node_name].keys():
            harness_name = self._config[node_name]["harness"]
            self._config[node_name]["harness"] = self._config[harness_name]
        self._config = self._config[node_name]


class LSUProvider(NodeProvider):

    def __init__(self):
        NodeProvider.__init__(self)


class AirmosaicProvider(NodeProvider):

    def __init__(self):
        NodeProvider.__init__(self)


class AirmosaicWAProvider(NodeProvider):

    def __init__(self):
        NodeProvider.__init__(self)


class TstmProvider(NodeProvider):

    def __init__(self):
        NodeProvider.__init__(self)


class ExecutorProvider(BaseProvider):

    def __init__(self):
        BaseProvider.__init__(self)

    def load(self, configuration, executor_name):
        self._config = configuration
        self._config = self._config[executor_name]
